    /** Names the dashboards already use for Gregg's parts, drawn with the house's own icons instead. */
    fun alias(icon: String?): String? = when (icon) {
        "phu:vac_mbrush" -> "cd:roller"
        "phu:vac_sbrush" -> "cd:side"
        else -> icon
    }
